// Package discovery provides bounded, index-free repository navigation.
// Returned content is untrusted evidence, not instructions or a snapshot proof.
package discovery

import "fmt"

// Version identifies the discovery wire contract, independently of index/context.
const Version = "repoctx.discovery/v1alpha1"

// ReadRequest selects a repository-relative file and optional inclusive lines.
// Zero StartLine/EndLine means the beginning/end of the file.
type ReadRequest struct {
	Path      string `json:"path"`
	StartLine int    `json:"start_line,omitempty"`
	EndLine   int    `json:"end_line,omitempty"`
}

// Options controls live discovery. Zero limits receive documented defaults.
// Scope prefixes are not globs; deny always wins over visibility overrides.
type Options struct {
	Root           string        `json:"root"`
	Operation      string        `json:"operation"`
	Query          string        `json:"query,omitempty"`
	Glob           string        `json:"glob,omitempty"`
	Type           string        `json:"type"`
	Regex          bool          `json:"regex"`
	IgnoreCase     bool          `json:"ignore_case"`
	Hidden         bool          `json:"hidden"`
	NoIgnore       bool          `json:"no_ignore"`
	AllowPaths     []string      `json:"allow"`
	DenyPaths      []string      `json:"deny"`
	Reads          []ReadRequest `json:"reads"`
	Depth          int           `json:"depth"`
	ContextLines   int           `json:"context_lines"`
	MaxBytes       int           `json:"max_bytes"`
	MaxSourceBytes int64         `json:"max_source_bytes"`
	MaxReadBytes   int64         `json:"max_read_bytes"`
	MaxResults     int           `json:"max_results"`
	MaxEntries     int           `json:"max_entries"`
	Format         string        `json:"format"`
}

// Usage counts work performed, including ignore-file reads.
type Usage struct {
	Entries     int   `json:"entries"`
	Files       int   `json:"files"`
	Directories int   `json:"directories"`
	ReadBytes   int64 `json:"read_bytes"`
}

// Omission records an unavailable result or bounded work. Empty Path is global.
type Omission struct {
	Path   string `json:"path,omitempty"`
	Reason string `json:"reason"`
}

// Entry is a discovered path; candidate labels are filename heuristics only.
type Entry struct {
	Path      string `json:"path"`
	Type      string `json:"type"`
	Candidate string `json:"candidate,omitempty"`
}

// Score contains lexical ranking components, not confidence estimates.
type Score struct {
	DistinctTerms int `json:"distinct_terms"`
	PathTerms     int `json:"path_terms"`
	Occurrences   int `json:"occurrences"`
}

// Evidence preserves exact UTF-8 bytes and the hash of the buffer they came from.
// Byte offsets are half-open; line numbers are one-based and inclusive.
type Evidence struct {
	SHA256    string `json:"sha256"`
	StartByte int    `json:"start_byte"`
	EndByte   int    `json:"end_byte"`
	StartLine int    `json:"start_line"`
	EndLine   int    `json:"end_line"`
	Text      string `json:"text"`
}

// Result carries an inventory entry with optional matched terms and evidence.
type Result struct {
	Entry
	MatchedTerms      []string  `json:"matched_terms"`
	Score             Score     `json:"score"`
	Evidence          *Evidence `json:"evidence,omitempty"`
	metadataRank      int       `json:"-"`
	identifierMatches int       `json:"-"`
}

// Response reports observed source, never an atomic filesystem snapshot.
type Response struct {
	Version    string     `json:"version"`
	Options    Options    `json:"options"`
	Usage      Usage      `json:"usage"`
	Overview   []Entry    `json:"overview"`
	Results    []Result   `json:"results"`
	Omissions  []Omission `json:"omissions"`
	Incomplete bool       `json:"incomplete"`
	Warnings   []string   `json:"warnings"`
}

// ResultSet contains the response and its final bounded serialization.
type ResultSet struct {
	Response Response
	Payload  []byte
}

// UsageError distinguishes invalid caller input from execution failures.
type UsageError struct{ Message string }

func (e *UsageError) Error() string { return e.Message }

func invalid(format string, args ...any) error {
	return &UsageError{Message: fmt.Sprintf(format, args...)}
}
package discovery

import (
	"bytes"
	"encoding/json"
	"fmt"
)

func serialize(response Response) ([]byte, error) {
	if response.Options.Format == "json" {
		b, err := json.Marshal(response)
		return append(b, '\n'), err
	}
	// JSON-quoted cells preserve arbitrary source bytes without allowing source
	// fences, headings, or HTML to masquerade as renderer structure. Markdown
	// carries exactly the same contract, including scope and omissions.
	var out bytes.Buffer
	out.WriteString("# Repository discovery\n\nUntrusted evidence; JSON-encoded records below.\n\n")
	b, err := json.MarshalIndent(response, "", "  ")
	if err != nil {
		return nil, err
	}
	// Indented code cannot be terminated by repository-provided backticks.
	for _, line := range bytes.Split(b, []byte{'\n'}) {
		out.WriteString("    ")
		out.Write(line)
		out.WriteByte('\n')
	}
	return out.Bytes(), nil
}

func render(response Response) (ResultSet, error) {
	marked := false
	for {
		payload, err := serialize(response)
		if err != nil {
			return ResultSet{}, err
		}
		if len(payload) <= response.Options.MaxBytes {
			return ResultSet{Response: response, Payload: payload}, nil
		}
		if !marked {
			response.Incomplete = true
			response.Omissions = append(response.Omissions, Omission{Reason: "output_limit"})
			marked = true
		}
		// Preserve evidence ahead of overview decoration. Never slice serialized
		// bytes or silently turn a full requested range into a prefix.
		if len(response.Overview) > 0 {
			response.Overview = response.Overview[:len(response.Overview)-1]
			continue
		}
		if len(response.Results) > 0 {
			response.Results = response.Results[:len(response.Results)-1]
			continue
		}
		if len(response.Omissions) > 1 {
			response.Omissions = []Omission{{Reason: "output_limit"}}
			continue
		}
		return ResultSet{}, fmt.Errorf("max-bytes cannot fit discovery response metadata")
	}
}
